window.SL_DATA.questions.push(
  { id:"ACC-Q060", board:"CBSE", klass:"11", subject:"ACC", chapter:1, topic:"ACC-1-10", type:"mcq", diff:"easy",
    q:{en:"Meena didi started her shop with ₹50,000 of her savings. Out of it she bought a fridge for ₹20,000 and goods for ₹25,000. Her CAPITAL is:", hi:"मीना दीदी ने ₹50,000 की बचत से दुकान शुरू की। उसमें से ₹20,000 का फ्रिज और ₹25,000 का माल खरीदा। उनकी पूंजी है:"},
    opts:{en:["₹50,000","₹30,000","₹25,000","₹5,000"], hi:["₹50,000","₹30,000","₹25,000","₹5,000"]},
    correct:"A", exp:{en:"Capital is the total amount the owner invests in the business — ₹50,000. How she spends it (fridge, goods, cash in hand) only changes the FORM of the assets.", hi:"पूंजी स्वामी द्वारा व्यवसाय में लगाई कुल राशि है — ₹50,000। खर्च का ढंग (फ्रिज, माल, नकद) केवल संपत्तियों का रूप बदलता है।"},
    tags:["case","story","exam-important"], source:"SelfLearn story case", status:"published" },
  { id:"ACC-Q061", board:"CBSE", klass:"11", subject:"ACC", chapter:1, topic:"ACC-1-10", type:"mcq", diff:"easy",
    q:{en:"Ramu uncle takes groceries worth ₹800 from Meena didi's shop on udhaar. In the shop's books Ramu uncle is a:", hi:"रामू चाचा मीना दीदी की दुकान से ₹800 का किराना उधार ले जाते हैं। दुकान की पुस्तकों में रामू चाचा हैं:"},
    opts:{en:["Creditor","Debtor","Investor","Employee"], hi:["लेनदार","देनदार","निवेशक","कर्मचारी"]},
    correct:"B", exp:{en:"He owes money TO the business after a credit sale — a debtor, shown on the asset side. Remember: Debtor Deta hai.", hi:"उधार बिक्री के बाद वे व्यवसाय को धन देंगे — देनदार, संपत्ति पक्ष में। याद रखें: देनदार देता है।"},
    tags:["case","story","exam-important"], source:"SelfLearn story case", status:"published" },
  { id:"ACC-Q062", board:"CBSE", klass:"11", subject:"ACC", chapter:1, topic:"ACC-1-10", type:"mcq", diff:"easy",
    q:{en:"Meena didi buys sugar sacks worth ₹5,000 on credit from the wholesaler. Until she pays, the wholesaler is her:", hi:"मीना दीदी थोक व्यापारी से ₹5,000 की चीनी उधार खरीदती हैं। भुगतान तक थोक व्यापारी उनके लिए है:"},
    opts:{en:["Debtor","Creditor","Customer","Partner"], hi:["देनदार","लेनदार","ग्राहक","साझेदार"]},
    correct:"B", exp:{en:"The business owes HIM money after a credit purchase — a creditor, shown on the liabilities side. Creditor ko Chukana hai.", hi:"उधार खरीद के बाद व्यवसाय को उन्हें धन देना है — लेनदार, दायित्व पक्ष में। लेनदार को चुकाना है।"},
    tags:["case","story"], source:"SelfLearn story case", status:"published" },
  { id:"ACC-Q063", board:"CBSE", klass:"11", subject:"ACC", chapter:1, topic:"ACC-1-10", type:"mcq", diff:"medium",
    q:{en:"Rats destroy stock worth ₹3,000 in Meena didi's store room. In accounting this is a:", hi:"मीना दीदी के भंडार में चूहे ₹3,000 का स्टॉक नष्ट कर देते हैं। लेखांकन में यह है:"},
    opts:{en:["An expense","A loss","Drawings","A liability"], hi:["व्यय","हानि","आहरण","दायित्व"]},
    correct:"B", exp:{en:"Money's worth gone with NO benefit in return is a loss (like fire or theft). An expense is a cost incurred TO EARN revenue.", hi:"बिना किसी लाभ के धन की क्षति हानि है (आग या चोरी जैसी)। व्यय वह लागत है जो आगम कमाने के लिए की जाए।"},
    tags:["case","story","exam-important"], source:"SelfLearn story case", status:"published" },
  { id:"ACC-Q064", board:"CBSE", klass:"11", subject:"ACC", chapter:1, topic:"ACC-1-10", type:"mcq", diff:"medium",
    q:{en:"Meena didi sells her old weighing scale (bought for ₹4,000) for ₹4,500. The ₹500 she made is:", hi:"मीना दीदी ₹4,000 में खरीदा पुराना तराज़ू ₹4,500 में बेचती हैं। कमाए ₹500 हैं:"},
    opts:{en:["Profit","Gain","Revenue","Interest"], hi:["लाभ","आकस्मिक लाभ (Gain)","आगम","ब्याज"]},
    correct:"B", exp:{en:"Selling an old asset is INCIDENTAL to her grocery business — such profit is a gain. Profit comes from normal operations (selling groceries).", hi:"पुरानी संपत्ति बेचना किराना व्यापार से आकस्मिक है — ऐसा लाभ Gain कहलाता है। लाभ सामान्य संचालन (किराना बिक्री) से आता है।"},
    tags:["case","story","exam-important"], source:"SelfLearn story case", status:"published" },
  { id:"ACC-Q065", board:"CBSE", klass:"11", subject:"ACC", chapter:1, topic:"ACC-1-5", type:"mcq", diff:"easy",
    q:{en:"The bank manager studies Meena didi's account register before approving her ₹1 lakh loan. As a lender, he is mainly checking:", hi:"₹1 लाख के ऋण से पहले बैंक मैनेजर मीना दीदी का रजिस्टर देखता है। ऋणदाता के रूप में वह मुख्यतः जाँचता है:"},
    opts:{en:["Her honesty and behaviour","The shop's ability to repay the loan","The shop's decoration","How old the shop is"],
          hi:["उनकी ईमानदारी और व्यवहार","दुकान की ऋण चुकाने की क्षमता","दुकान की सजावट","दुकान कितनी पुरानी है"]},
    correct:"B", exp:{en:"Lenders are external users interested in creditworthiness and repaying capacity — shown by profits and financial position in the accounts.", hi:"ऋणदाता बाहरी उपयोगकर्ता हैं जिन्हें साख व भुगतान क्षमता में रुचि है — जो खातों के लाभ व वित्तीय स्थिति से दिखती है।"},
    tags:["case","story"], source:"SelfLearn story case", status:"published" },
  { id:"ACC-Q066", board:"CBSE", klass:"11", subject:"ACC", chapter:2, topic:"ACC-2-2", type:"mcq", diff:"medium",
    q:{en:"Meena didi pays her son's school fees ₹2,000 from the shop's cash box. In the SHOP's books this is recorded as:", hi:"मीना दीदी दुकान के गल्ले से बेटे की स्कूल फीस ₹2,000 चुकाती हैं। दुकान की पुस्तकों में यह दर्ज होगा:"},
    opts:{en:["School fees expense","Drawings","Loss","It is not recorded at all"], hi:["स्कूल फीस व्यय","आहरण","हानि","बिल्कुल दर्ज नहीं होगा"]},
    correct:"B", exp:{en:"Business funds used for the owner's personal purpose = drawings (reduces capital). It is recorded because shop money moved — but never as a business expense (entity concept).", hi:"स्वामी के निजी काम में व्यवसाय का धन = आहरण (पूंजी घटती है)। दुकान का धन चला इसलिए दर्ज होगा — पर व्यवसाय का व्यय कभी नहीं (इकाई अवधारणा)।"},
    tags:["case","story","exam-important"], source:"SelfLearn story case", status:"published" },
  { id:"ACC-Q067", board:"CBSE", klass:"11", subject:"ACC", chapter:2, topic:"ACC-2-6", type:"mcq", diff:"medium",
    q:{en:"Meena didi's fridge cost ₹20,000. She paid ₹500 for the tempo and ₹300 to the electrician to install it. In the books the fridge is recorded at:", hi:"मीना दीदी का फ्रिज ₹20,000 का था। टेम्पो के ₹500 और लगवाने के लिए मिस्त्री के ₹300 दिए। पुस्तकों में फ्रिज दर्ज होगा:"},
    opts:{en:["₹20,000","₹20,500","₹20,800","₹20,300"], hi:["₹20,000","₹20,500","₹20,800","₹20,300"]},
    correct:"C", exp:{en:"Cost concept: record at purchase price PLUS all costs of making the asset ready for use — 20,000 + 500 + 300 = ₹20,800.", hi:"लागत अवधारणा: क्रय मूल्य + उपयोग योग्य बनाने की सभी लागतें — 20,000 + 500 + 300 = ₹20,800।"},
    tags:["case","story","numerical","exam-important"], source:"SelfLearn story case", status:"published" },
  { id:"ACC-Q068", board:"CBSE", klass:"11", subject:"ACC", chapter:2, topic:"ACC-2-4", type:"mcq", diff:"medium",
    q:{en:"Meena didi charges only ₹2,000 of her ₹20,000 fridge to each year's profit, spreading it over 10 years. Which concept justifies this?", hi:"मीना दीदी ₹20,000 के फ्रिज में से हर वर्ष के लाभ पर केवल ₹2,000 डालती हैं, 10 वर्षों में बाँटकर। कौन-सी अवधारणा इसे उचित ठहराती है?"},
    opts:{en:["Business entity","Going concern","Money measurement","Full disclosure"], hi:["व्यावसायिक इकाई","चालू व्यवसाय","मुद्रा मापन","पूर्ण प्रकटीकरण"]},
    correct:"B", exp:{en:"Going concern assumes the shop will run for years — so the asset's cost is spread (depreciated) over its useful life instead of hitting one year.", hi:"चालू व्यवसाय मानता है कि दुकान वर्षों चलेगी — इसलिए संपत्ति की लागत एक वर्ष पर डालने के बजाय उपयोगी जीवन पर बाँटी (ह्रास) जाती है।"},
    tags:["case","story","exam-important"], source:"SelfLearn story case", status:"published" },
  { id:"ACC-Q069", board:"CBSE", klass:"11", subject:"ACC", chapter:2, topic:"ACC-2-8", type:"mcq", diff:"medium",
    q:{en:"Ramu uncle takes ₹800 of groceries on udhaar in March and pays in June. Under the accrual basis, this sale is revenue of:", hi:"रामू चाचा मार्च में ₹800 का किराना उधार लेते हैं और जून में चुकाते हैं। उपार्जन आधार पर यह बिक्री किस माह का आगम है?"},
    opts:{en:["June, when cash came","March, when the sale was made","Half in March, half in June","Whichever month Meena chooses"],
          hi:["जून, जब नकद आया","मार्च, जब बिक्री हुई","आधा मार्च, आधा जून","जो माह मीना चुनें"]},
    correct:"B", exp:{en:"Revenue is recognised when the legal right to receive arises — at the point of sale in March, not when cash arrives.", hi:"आगम तब मान्य होता है जब पाने का कानूनी अधिकार बने — मार्च में बिक्री के समय, नकद आने पर नहीं।"},
    tags:["case","story","exam-important"], source:"SelfLearn story case", status:"published" },
  { id:"ACC-Q070", board:"CBSE", klass:"11", subject:"ACC", chapter:2, topic:"ACC-2-10", type:"mcq", diff:"hard",
    q:{en:"To impress the bank, Suresh bhaiya quietly changes his stock valuation method this year (profit looks 15% higher) and does not mention it anywhere. Which concepts has he violated?", hi:"बैंक को प्रभावित करने के लिए सुरेश भैया चुपचाप इस वर्ष स्टॉक मूल्यांकन विधि बदल देते हैं (लाभ 15% अधिक दिखता है) और कहीं उल्लेख नहीं करते। उन्होंने किन अवधारणाओं का उल्लंघन किया?"},
    opts:{en:["Consistency and Full disclosure","Entity and Accounting period","Money measurement and Cost","Matching and Materiality"],
          hi:["एकरूपता और पूर्ण प्रकटीकरण","इकाई और लेखांकन अवधि","मुद्रा मापन और लागत","मिलान और सारता"]},
    correct:"A", exp:{en:"Methods must stay consistent year to year; a change is allowed only if fully disclosed along with its effect on profit.", hi:"विधियाँ वर्ष-दर-वर्ष एकरूप रहें; परिवर्तन तभी मान्य जब लाभ पर प्रभाव सहित पूर्ण प्रकटीकरण हो।"},
    tags:["case","story","exam-important"], source:"SelfLearn story case, NCERT Activity 1 adapted", status:"published" },
  { id:"ACC-Q071", board:"CBSE", klass:"11", subject:"ACC", chapter:2, topic:"ACC-2-13", type:"mcq", diff:"medium",
    q:{en:"Meena didi orders namkeen worth ₹10,000 from a supplier in ANOTHER state. GST rate is 18%. Her invoice will show:", hi:"मीना दीदी दूसरे राज्य के आपूर्तिकर्ता से ₹10,000 की नमकीन मँगाती हैं। GST दर 18%। उनके बीजक में होगा:"},
    opts:{en:["CGST ₹900 + SGST ₹900","IGST ₹1,800","Only CGST ₹1,800","No GST on food items"],
          hi:["CGST ₹900 + SGST ₹900","IGST ₹1,800","केवल CGST ₹1,800","खाद्य पर GST नहीं"]},
    correct:"B", exp:{en:"An inter-state purchase attracts IGST at the full rate: 18% of 10,000 = ₹1,800. CGST+SGST split applies only within one state.", hi:"अंतर-राज्यीय खरीद पर पूर्ण दर से IGST: 10,000 का 18% = ₹1,800। CGST+SGST विभाजन केवल राज्य के भीतर।"},
    tags:["case","story","numerical","gst"], source:"SelfLearn story case", status:"published" }
);
